const SOUND_DATA_URI = 'data:audio/wav;base64,,'  // eslint-disable-line @typescript-eslint/no-unused-vars
export type NotificationType = 'system' | 'chat' | 'task' | 'comment' | 'approval' | 'deadline' | 'leaves' | 'priority_task' | 'security' | 'info';

const SOUND_VOLUME = 0.3;
const SOUND_COOLDOWN_MS = 1000;

let lastSoundTime = 0;
let audioInstance: HTMLAudioElement | null = null;

export function playNotificationSound(type: NotificationType = 'system'): void {
  const now = Date.now();
  if (now - lastSoundTime < SOUND_COOLDOWN_MS) return;

  try {
    if (!audioInstance) {
      audioInstance = new Audio(SOUND_DATA_URI);
    }
    audioInstance.volume = SOUND_VOLUME;
    audioInstance.currentTime = 0;
    audioInstance.play().catch(() => {
      // Auto-play may be blocked; this is expected in some browsers
    });
    lastSoundTime = now;
  } catch {
    // Audio play failed silently
  }
}

export function stopNotificationSound(): void {
  if (audioInstance) {
    audioInstance.pause();
    audioInstance = null;
  }
}
